class RiskGate:
    def __init__(self, max_dd=0.10, max_daily_loss=0.02):
        self.peak = 1.0
        self.day_open = 1.0
        self.max_dd = max_dd
        self.max_daily_loss = max_daily_loss
        self.killed = False

    def check(self, equity):
        self.peak = max(self.peak, equity)
        dd = (equity - self.peak) / self.peak
        daily_loss = (equity - self.day_open) / self.day_open
        if dd < -self.max_dd or daily_loss < -self.max_daily_loss:
            self.killed = True
        return not self.killed  # False -> flatten, halt

    def new_day(self, equity):
        self.day_open = equity

import threading, time

class Heartbeat:
    def __init__(self, timeout_s=60, on_flat=None):
        self.timeout_s = timeout_s
        self.on_flat = on_flat or (lambda: None)
        self._last = time.monotonic()
        self._t = threading.Thread(target=self._watch, daemon=True)
        self._t.start()

    def beat(self):
        self._last = time.monotonic()

    def _watch(self):
        while True:
            time.sleep(self.timeout_s / 4)
            if time.monotonic() - self._last > self.timeout_s:
                self.on_flat()  # flatten positions, halt loop
                break
